package com.zalolite.chat.domain;

import java.util.Locale;

public enum MessageType {
    TEXT,
    IMAGE,
    VIDEO,
    FILE,
    STICKER,
    /** Generated by the server (member joined, group renamed...). Clients cannot send it. */
    SYSTEM;

    /** Lenient parsing of what clients send; unknown or missing values mean TEXT. */
    public static MessageType parse(String raw) {
        if (raw == null || raw.isBlank()) {
            return TEXT;
        }
        return switch (raw.trim().toUpperCase(Locale.ROOT)) {
            case "IMAGE", "PHOTO" -> IMAGE;
            case "VIDEO" -> VIDEO;
            case "FILE", "DOCUMENT", "DOC" -> FILE;
            case "STICKER", "EMOTION", "EMOJI" -> STICKER;
            case "SYSTEM" -> SYSTEM;
            default -> TEXT;
        };
    }
}
